/** \file crypto_ctf.h
 *
 * \brief Mini CTF of classical cryptography: César, ROT13, Morse, binaire, hexa, base64, atbash, scytale, XOR,
 * Vigenère, hash tronqué... in French, in order of difficulty.
 *
 * The texts are generated by tools/crypto_ctf_make.py (the solution file, with the answers): the firmware only has
 * the SipHash of the answers, and the pieces of the final flag SECSEA{...} masked by a SipHash stream.
 * Each solved challenge gives a piece of the flag, all of them give the whole flag.
 * The progress (mask of the solved challenges, bit i = challenge i) is stored by the caller.
 * */

#ifndef _CRYPTO_CTF_H
#define _CRYPTO_CTF_H

#include <stdbool.h>
#include <stdint.h>

#define CRYPTO_CTF_ANSWER_MAX 32  /* Characters of an answer, after normalization */
#define CRYPTO_CTF_FLAG_MAX 48  /* Size of a buffer for the final flag, with the final 0 */

/** \brief Number of challenges (at most 32). */
int crypto_ctf_count(void);

/** \brief Title of the challenge \p i (fits in the medium font), "" if \p i is out of range. */
const char *crypto_ctf_title(int i);

/** \brief Text of the challenge: at most 7 lines separated by \\n, that fit in the small font on 196 pixels. */
const char *crypto_ctf_text(int i);

/** \brief Hint: at most 3 lines separated by \\n, "" if none. */
const char *crypto_ctf_hint(int i);

/** \brief Dots, dashes, spaces between letters and " / " between words, to play with the buzzer and the LEDs,
 * NULL if the challenge has no Morse code. */
const char *crypto_ctf_morse(int i);

/** \brief Whether \p answer is the answer of the challenge \p i: letters in any case, spaces at the ends and
 * repeated spaces ignored. */
bool crypto_ctf_check(int i, const char *answer);

/** \brief The piece of the final flag given by the challenge \p i, if it is solved in \p solved_mask.
 * \return false if it is not solved or \p buf is too small. */
bool crypto_ctf_piece(int i, uint32_t solved_mask, char *buf, int len);

/** \brief The final flag SECSEA{...} in \p buf when all the challenges are solved in \p solved_mask.
 * \return false (and \p buf empty) otherwise. */
bool crypto_ctf_final_flag(uint32_t solved_mask, char *buf, int len);

#endif /* _CRYPTO_CTF_H */
